(()=>{
const MUSIC_VOLUME=.1,FIRST_SILENCE_SECONDS=1,FIRST_FADE_SECONDS=4;
const button=document.querySelector('#music-toggle'),caption=button.nextElementSibling,status=document.querySelector('#loading-music-state');
let ducked=false;
let muted=false,context,gain,buffer,source,startedAt=0,sourceCount=0,ready=false,failed=false,trimStart=0,trimEnd=0,crossfade=0,outputWarmed=false,preparedAt=0,playRequestedAt=0,waitingForGesture=false,revealAudioLead=0,firstPlaybackStarted=false;
// Every fresh visit starts with music enabled; mute only affects this visit.
function update(){const playing=!!source&&context?.state==='running';if(playing)firstPlaybackStarted=true;const label=muted?'Unmute music':playing?'Mute music':'Play music';button.setAttribute('aria-label',label);button.title=label;button.setAttribute('aria-pressed',String(muted));button.dataset.muted=String(muted);caption.textContent=muted?'Music off':'Music on';}
function musicLevel(){return ducked?MUSIC_VOLUME*.18:MUSIC_VOLUME;}
function setDucked(value){if(ducked===value)return;ducked=value;if(!gain||!context||muted||!source)return;const now=context.currentTime;gain.gain.cancelScheduledValues(now);gain.gain.setValueAtTime(gain.gain.value,now);gain.gain.linearRampToValueAtTime(musicLevel(),now+(value?.3:.8));}
function setMuted(value){muted=value;if(muted)window.atlasNarration?.stop();if(muted&&source){source.stop();source.disconnect();source=null;startedAt=0;}if(gain){gain.gain.cancelScheduledValues(context.currentTime);gain.gain.setValueAtTime(muted||!firstPlaybackStarted?0:musicLevel(),context.currentTime);}update();}
function unavailable(){failed=true;status.textContent='Music unavailable';button.disabled=true;button.setAttribute('aria-label','Background music unavailable');caption.textContent='No audio';}
function warmOutput(){if(outputWarmed||!context||context.state!=='running')return;const silent=context.createBufferSource();silent.buffer=context.createBuffer(1,128,context.sampleRate);silent.connect(context.destination);silent.onended=()=>silent.disconnect();silent.start();outputWarmed=true;}
function ensureContext(){if(context)return context;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Audio unavailable');context=new Audio();context.addEventListener('statechange',()=>{warmOutput();update();});return context;}
function unlockOutput(){if(muted||failed)return;try{ensureContext();warmOutput();context.resume().then(warmOutput).catch(()=>{});}catch{}}
async function prepare(bytes){try{status.textContent='Preparing seamless music loop…';ensureContext();unlockOutput();const decoded=await context.decodeAudioData(bytes),channels=Array.from({length:decoded.numberOfChannels},(_,i)=>decoded.getChannelData(i)),step=Math.max(1,Math.round(decoded.sampleRate*.01));let first=0,last=decoded.length;const quiet=(lo,hi)=>channels.every(data=>{let energy=0;for(let i=lo;i<hi;i++)energy+=data[i]*data[i];return Math.sqrt(energy/Math.max(1,hi-lo))<.00035;});while(first+step<last-decoded.sampleRate&&quiet(first,first+step))first+=step;while(last-step>first+decoded.sampleRate&&quiet(last-step,last))last-=step;first=Math.max(0,first-step);last=Math.min(decoded.length,last+step);trimStart=first/decoded.sampleRate;trimEnd=(decoded.length-last)/decoded.sampleRate;const frames=last-first,fade=Math.min(Math.round(decoded.sampleRate*.06),Math.floor(frames/10));buffer=context.createBuffer(decoded.numberOfChannels,frames,decoded.sampleRate);for(let channel=0;channel<channels.length;channel++){const data=channels[channel],out=buffer.getChannelData(channel);for(let i=0;i<frames;i++){let sample=data[first+i];if(i>=frames-fade){const j=i-(frames-fade),t=j/(fade-1);sample=sample*(1-t)+data[first+j]*t;}out[i]=sample;}}crossfade=fade/decoded.sampleRate;gain=context.createGain();gain.gain.value=0;gain.connect(context.destination);ready=true;preparedAt=performance.now();status.textContent='Music loaded';update();return true;}catch{unavailable();return false;}}
async function play(){if(!ready||muted||failed)return false;if(!source){source=context.createBufferSource();source.buffer=buffer;source.loop=true;source.loopStart=crossfade;source.loopEnd=buffer.duration;source.connect(gain);startedAt=context.currentTime;gain.gain.cancelScheduledValues(startedAt);gain.gain.setValueAtTime(firstPlaybackStarted?musicLevel():0,startedAt);if(!firstPlaybackStarted){gain.gain.setValueAtTime(0,startedAt+FIRST_SILENCE_SECONDS);gain.gain.linearRampToValueAtTime(musicLevel(),startedAt+FIRST_SILENCE_SECONDS+FIRST_FADE_SECONDS);}source.start(startedAt+(firstPlaybackStarted?0:FIRST_SILENCE_SECONDS));sourceCount++;}try{const resume=context.resume();await Promise.race([resume,new Promise(resolve=>setTimeout(resolve,180))]);}catch{}update();return context.state==='running';}
async function startForReveal(){if(muted||failed||!ready)return;playRequestedAt=performance.now();status.hidden=true;waitingForGesture=false;await play();}


button.addEventListener('click',()=>{setMuted(!muted);if(!muted)play();});
function unlock(event){if(event.target.closest('#music-toggle')||muted)return;unlockOutput();if(document.body.classList.contains('world-ready')&&ready&&(!source||context?.state!=='running'))play();}
for(const event of ['pointerdown','pointerup','click','touchend'])document.addEventListener(event,unlock,{capture:true,passive:true});document.addEventListener('keydown',event=>{if(!event.repeat&&['Enter',' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key))unlock(event);},{capture:true});
window.atlasMusic={prepare,startForReveal,setDucked,getContext:ensureContext,get state(){return{ready,muted,playing:!!source&&context?.state==='running',duration:buffer?.duration,trimStart,trimEnd,crossfade,sourceCount,loop:source?.loop,contextState:context?.state,currentTime:context?.currentTime,startedAt,engine:'audio-buffer',volume:gain?.gain.value,targetVolume:MUSIC_VOLUME,firstSilenceSeconds:FIRST_SILENCE_SECONDS,firstFadeSeconds:FIRST_FADE_SECONDS,firstPlaybackStarted,outputWarmed,preparedAt,playRequestedAt,waitingForGesture,revealAudioLead};},get source(){return source;}};update();
})();
